const out = [];
const seen = new Set();
// one input item per page of Notion results now, not just the first page
for (const item of $input.all()) {
  for (const p of (item.json.results || [])) {
    if (!p || !p.id || seen.has(p.id)) continue;
    seen.add(p.id);
    const props = p.properties || {};
    const title = (props["สินค้า"] || {}).title || [];
    out.push({ json: {
      page_id: p.id,
      name: title.map(t => t.plain_text).join(""),
      full: props["ราคาเต็ม"] ? props["ราคาเต็ม"].number : null,
      sale: props["ราคาลด"] ? props["ราคาลด"].number : null,
      link: props["ลิงก์Affiliate"] ? props["ลิงก์Affiliate"].url : "",
      cat: (props["หมวด"] && props["หมวด"].select) ? props["หมวด"].select.name : ""
    }});
  }
}
return out;

const raw = ($json.content && $json.content[0] && $json.content[0].text ? $json.content[0].text : '').trim();
// สั่งให้ตอบ JSON ล้วน แต่บางรอบยังครอบ code block หรือมีข้อความนำ — ดึงก้อน {...} ออกมาก่อน
let cap = '', desc = '';
const m = raw.match(/\{[\s\S]*\}/);
if (m) {
  try {
    const o = JSON.parse(m[0]);
    cap = String(o.caption || '').trim();
    desc = String(o.desc || '').trim();
  } catch (e) {}
}
// พาร์สไม่ได้ = ถอยไปใช้ทั้งก้อนเป็นแคปชันแบบเดิม ดีกว่าปล่อยให้ดีลไม่มีแคปชัน
if (!cap) cap = raw.replace(/```[a-z]*/gi, '').replace(/```/g, '').trim();
const d = $('Split New').item.json;
const pct = d.full && d.sale ? Math.round((1 - d.sale / d.full) * 100) : null;
let priceLine = '';
if (d.sale) priceLine = '💥 เหลือ ' + d.sale + ' บาท' + (pct ? ' (ลด ' + pct + '%)' : '');
else if (d.full) priceLine = '💰 ราคา ' + d.full + ' บาท';
const body = (priceLine ? priceLine + '\n' : '') + '👉 ' + d.link;
const text = cap + '\n\n' + body + '\n\n#ป้ายยา #ดีลเด็ด (ลิงก์ affiliate)';
return { json: { page_id: d.page_id, name: d.name, text, desc } };

// 29 ต.ค. 69 ด่านตรวจแถว 'รอตรวจ' (แถวที่ Claude ฝั่ง claude.ai สร้างตรงใน Notion เคยค้างตลอดกาล) — รวมทุกหน้าเป็น item เดียว
const rows = $('Query Pending').all().flatMap(i => i.json.results || []);
if (!rows.length) return [];
return [{ json: { pending: rows } }];

// ตรวจแถว 'รอตรวจ' ทีละแถว (เก่าก่อน) → ผ่าน = อนุมัติแล้ว แต่เติมคิวแค่ให้ 'อนุมัติแล้ว' รวม ≤ QUEUE_MAX (2 รอบโพสต์)
// ไม่งั้นดีลใหม่จาก intake ต้องรอหลังของค้างหลายร้อยแถว · ไม่ผ่าน = ค้าง รอตรวจ + แจ้ง #deals (ครั้งเดียวต่อแถว)
const QUEUE_MAX = 12;
const CLAIM = new RegExp(String.raw`รักษา(?:โรค|อาการ|สิว|ฝ้า|แผล|ผม|หาย)|หายขาด|บำบัด|บรรเทา|แก้ปวด|ป้องกันโรค|ต้านโรค|ภูมิคุ้มกัน|ต้านอนุมูล|ลดน้ำหนัก|ลดความอ้วน|เผาผลาญ|ลดไขมัน|ลดพุง|ลดคอเลส|น้ำตาลในเลือด|ความดัน(?:โลหิต|สูง)|ดีท็อก|ล้างสารพิษ|บำรุงร่างกาย|บำรุงสมอง|เพิ่มสมรรถภาพ|ฟื้นฟูร่างกาย|ชะลอวัย|ต่อต้านริ้วรอย|ลดริ้วรอย|ลบริ้วรอย|ยกกระชับ|ผิวขาว|ขาวใส|หน้าใส|ผิวใส|ลดสิว|สิวหาย|ฝ้าจาง|ฆ่าเชื้อ|ขจัดเชื้อ|กำจัดเชื้อ|ยับยั้งเชื้อ|แบคทีเรีย|ไวรัส|99\.9|ปกป้องผิว|ปกป้องมือ|ไม่มีผลข้างเคียง|ปลอดภัย ?100|เห็นผล|โปรตีนสูง|แคลเซียมสูง|วิตามินสูง|ผ่อนคลายกล้ามเนื้อ`);   // = CLAIM_RE ใน deal-video server.py (กฎโฆษณา อย.)
const AFF = /^https:\/\/(s\.shopee\.co\.th|shope\.ee|s\.lazada\.co\.th|c\.lazada\.co\.th|vt\.tiktok\.com|(www\.)?tiktok\.com)\//;
const txt = (p, k) => (((p.properties || {})[k] || {})[k === 'สินค้า' ? 'title' : 'rich_text'] || []).map(t => t.plain_text).join('');
const norm = s => s.replace(/\s+/g, ' ').trim().toLowerCase();
const pending = $('Pending List').first().json.pending.slice().sort((a, b) => a.created_time < b.created_time ? -1 : 1);
const posted = $('Query Posted').all().flatMap(i => i.json.results || []);
let room = Math.max(0, QUEUE_MAX - ($('Query Approved').first().json.results || []).length);
const pn = new Set(posted.map(p => norm(txt(p, 'สินค้า'))));
const pl = new Set(posted.map(p => (p.properties['ลิงก์Affiliate'] || {}).url).filter(Boolean));
const seen = new Set();
const out = [];
for (const p of pending) {
  const pr = p.properties, name = txt(p, 'สินค้า'), link = (pr['ลิงก์Affiliate'] || {}).url || '';
  const sale = (pr['ราคาลด'] || {}).number, full = (pr['ราคาเต็ม'] || {}).number;
  const r = [];
  if (!AFF.test(link)) r.push('ลิงก์ไม่ใช่ affiliate');
  if (!name.trim()) r.push('ไม่มีชื่อสินค้า');
  if (!txt(p, 'แคปชัน').trim()) r.push('ไม่มีแคปชัน');
  if (sale != null && sale <= 1) r.push('ราคาลด ' + sale + ' บาท');
  if (sale && full && full < sale) r.push('ราคาเต็มต่ำกว่าราคาลด');
  const k = norm(name);
  if (pn.has(k) || pl.has(link)) r.push('ซ้ำกับดีลที่โพสต์แล้ว');
  else if (seen.has(k) || (link && seen.has(link))) r.push('ซ้ำกับแถวรอตรวจอื่น');
  const m = (txt(p, 'แคปชัน') + ' ' + txt(p, 'คำบรรยาย')).match(CLAIM);
  if (m) r.push('อ้างสรรพคุณ "' + m[0] + '"');
  seen.add(k); if (link) seen.add(link);
  const ok = !r.length;
  if (ok && room <= 0) continue;   // ผ่านแต่คิวเต็ม → รอบหน้า
  if (ok) room--;
  out.push({ json: { id: p.id, name, ok, reasons: r } });
}
return out;

// สรุปเข้า #deals: อนุมัติกี่แถว + แถวไม่ผ่าน (แจ้งครั้งเดียวต่อแถว จำใน staticData 30 วัน)
const sd = $getWorkflowStaticData('global'); sd.reviewed = sd.reviewed || {};
const all = $('Review Pending').all().map(i => i.json);
const ok = all.filter(x => x.ok), bad = all.filter(x => !x.ok && !sd.reviewed[x.id]);
const now = Date.now();
for (const x of bad) sd.reviewed[x.id] = now;
for (const [k, t] of Object.entries(sd.reviewed)) if (now - t > 30 * 864e5) delete sd.reviewed[k];
if (!ok.length && !bad.length) return [];
const left = $('Pending List').first().json.pending.length - ok.length;
const L = [];
if (ok.length) L.push('✅ ด่านตรวจอนุมัติ ' + ok.length + ' ดีลจาก รอตรวจ → เข้าคิวโพสต์ (เหลือรอตรวจ ' + left + ')');
if (bad.length) {
  L.push('⚠️ ไม่ผ่านด่านตรวจ ' + bad.length + ' แถว — ค้างที่ รอตรวจ (แก้ใน Notion แล้วรอบหน้าตรวจใหม่เอง):');
  for (const x of bad.slice(0, 15)) L.push('• ' + x.name.slice(0, 60) + ' — ' + x.reasons.join(', '));
  if (bad.length > 15) L.push('… อีก ' + (bad.length - 15) + ' แถว');
}
return [{ json: { text: L.join('\n') } }];
